/**
 * The owner's badges and picture frames (T64), as drawings. The owner picked these from the
 * option sheets in docs/owner-reports/2026-10-11/ (rounds 1–4). Only the owner can wear them:
 * the server hands them out for the owner alone (public.profile_card, 0017).
 *
 * Plain SVG text, no pictures to load. Ids are made unique per use (OwnerArt.tsx). The classes
 * (oa-…) move as svgMotion.css says, following Account → Theme → Animations.
 */
export interface OwnerBadgeArt {
  name: string;
  line: string;
  look: string;
  viewBox: string;
  body: string;
}
export interface OwnerFrameArt {
  name: string;
  line: string;
  /** The drawing's square size (viewBox 0 0 box box). */
  box: number;
  /** The picture area's bounds [x, y, width, height], so it lines up with the normal picture size. */
  fit: [number, number, number, number];
  /** The picture's shape. */
  clip: string;
  /** Drawn behind and in front of the picture. */
  under: string;
  over: string;
}

